export function readablePartyColor(hex) {
  if (!hex || typeof hex !== 'string' || !hex.startsWith('#')) return '#f8fafc';
  let c = hex.slice(1);
  if (c.length === 3) c = c.split('').map(x => x + x).join('');
  if (c.length !== 6) return hex;
  const r = parseInt(c.slice(0, 2), 16) || 0;
  const g = parseInt(c.slice(2, 4), 16) || 0;
  const b = parseInt(c.slice(4, 6), 16) || 0;
  const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  if (lum < 0.32) {
    const boost = (v) => Math.min(255, Math.round(v + (255 - v) * 0.65));
    return '#' + [boost(r), boost(g), boost(b)].map(x => x.toString(16).padStart(2, '0')).join('');
  }
  return hex;
}

